PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','atendente')));
CREATE TABLE IF NOT EXISTS tutors(id INTEGER PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pets(id INTEGER PRIMARY KEY,name TEXT NOT NULL,tutor_id INTEGER NOT NULL REFERENCES tutors(id),species TEXT NOT NULL,breed TEXT NOT NULL,size TEXT NOT NULL,birth_date TEXT NOT NULL,weight REAL NOT NULL CHECK(weight>0),allergies TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS professionals(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN (CAST(X'5665746572696ec3a172696f' AS TEXT),'Petshop')),crmv TEXT NOT NULL DEFAULT '',specialty TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,weekdays TEXT NOT NULL DEFAULT '0,1,2,3,4',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN (CAST(X'436cc3ad6e696361' AS TEXT),'Petshop')),description TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),duration INTEGER NOT NULL CHECK(duration>0),professional_id INTEGER NOT NULL REFERENCES professionals(id));
CREATE TABLE IF NOT EXISTS appointments(id INTEGER PRIMARY KEY,pet_id INTEGER NOT NULL REFERENCES pets(id),service_id INTEGER NOT NULL REFERENCES services(id),professional_id INTEGER NOT NULL REFERENCES professionals(id),start TEXT NOT NULL,end TEXT NOT NULL,price_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Agendado' CHECK(status IN ('Agendado',CAST(X'436f6e636c75c3ad646f' AS TEXT),'Cancelado')));
CREATE INDEX IF NOT EXISTS agenda_interval ON appointments(professional_id,start,end);
CREATE TABLE IF NOT EXISTS records(id INTEGER PRIMARY KEY,pet_id INTEGER NOT NULL REFERENCES pets(id),professional_id INTEGER NOT NULL REFERENCES professionals(id),kind TEXT NOT NULL CHECK(kind IN ('Consulta','Vacina',CAST(X'4f627365727661c3a7c3a36f' AS TEXT))),date TEXT NOT NULL,notes TEXT NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),stock INTEGER NOT NULL CHECK(stock>=0));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,tutor_id INTEGER NOT NULL REFERENCES tutors(id),appointment_id INTEGER UNIQUE REFERENCES appointments(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0),description TEXT NOT NULL,total_cents INTEGER NOT NULL CHECK(total_cents>=0),status TEXT NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pago','Pendente')),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_cents INTEGER NOT NULL CHECK(unit_cents>=0),created TEXT NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS payment_settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO payment_settings VALUES('instance',lower(hex(randomblob(16))));
CREATE TABLE IF NOT EXISTS app_settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stripe_payments(order_id INTEGER PRIMARY KEY REFERENCES orders(id),session_id TEXT UNIQUE,amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',payment_intent TEXT);
